//! Parity gate: assert every Python-oracle case from `parity_fixture.txt`
//! produces the identical recorded token in Rust.
//!
//! The fixture is generated by `tests/parity_oracle.py`, which runs the real
//! `money.py` under the project venv. A Rust failure here is a parity failure,
//! not a test bug; do not edit the fixture to go green — fix the implementation
//! and regenerate from the oracle.

use std::cmp::Ordering;

use ezchain_decimal::{
    exact_precision, exact_product, exact_sum, floor_money, quantize_money, Decimal, ParseError,
};

const FIXTURE: &str = include_str!("parity_fixture.txt");

fn dec_token(value: &Decimal) -> String {
    format!("V:{}~{}", value.canonical(), value.str_repr())
}

fn parse_or_error(s: &str) -> Result<Decimal, String> {
    Decimal::parse(s).map_err(|err| match err {
        ParseError::NonFinite | ParseError::Syntax => "E:MoneyError".to_string(),
    })
}

fn run_case(op: &str, args: &[&str]) -> String {
    match op {
        "parse" => parse_or_error(args[0])
            .map(|v| dec_token(&v))
            .unwrap_or_else(|e| e),
        "ep" => {
            let extra = args[0].parse::<i32>().expect("valid extra in fixture");
            let mut values = Vec::with_capacity(args.len() - 1);
            for s in &args[1..] {
                match parse_or_error(s) {
                    Ok(v) => values.push(v),
                    Err(e) => return e,
                }
            }
            format!("I:{}", exact_precision(&values, extra))
        }
        "q" | "f" => match parse_or_error(args[0]) {
            Ok(value) => {
                let result = if op == "q" {
                    quantize_money(&value)
                } else {
                    floor_money(&value)
                };
                result
                    .map(|v| dec_token(&v))
                    .unwrap_or_else(|e| format!("E:{}", e.code()))
            }
            Err(e) => e,
        },
        "sum" => {
            let mut values = Vec::with_capacity(args.len());
            for s in args {
                match parse_or_error(s) {
                    Ok(v) => values.push(v),
                    Err(e) => return e,
                }
            }
            exact_sum(&values)
                .map(|v| dec_token(&v))
                .unwrap_or_else(|e| format!("E:{}", e.code()))
        }
        "prod" => {
            let mut values = Vec::with_capacity(args.len());
            for s in args {
                match parse_or_error(s) {
                    Ok(v) => values.push(v),
                    Err(e) => return e,
                }
            }
            exact_product(&values)
                .map(|v| dec_token(&v))
                .unwrap_or_else(|e| format!("E:{}", e.code()))
        }
        "cmp" => {
            let a = match parse_or_error(args[0]) {
                Ok(v) => v,
                Err(e) => return e,
            };
            let b = match parse_or_error(args[1]) {
                Ok(v) => v,
                Err(e) => return e,
            };
            match ezchain_decimal::money::compare(&a, &b) {
                Ordering::Less => "C:LT".to_string(),
                Ordering::Equal => "C:EQ".to_string(),
                Ordering::Greater => "C:GT".to_string(),
            }
        }
        other => panic!("unknown operation in fixture: {other}"),
    }
}

#[test]
fn python_oracle_parity() {
    let mut passed = 0usize;
    let mut failures: Vec<String> = Vec::new();

    for (index, line) in FIXTURE.lines().enumerate() {
        let fields: Vec<&str> = line.split('\t').collect();
        assert!(fields.len() >= 2, "malformed fixture line {}", index + 1);
        let op = fields[0];
        let expected = fields[fields.len() - 1];
        let actual = run_case(op, &fields[1..fields.len() - 1]);
        if actual == expected {
            passed += 1;
        } else {
            failures.push(format!(
                "line {} [{} {}]: expected {expected}, got {actual}",
                index + 1,
                op,
                fields[1..fields.len() - 1].join(" ")
            ));
        }
    }

    let total = FIXTURE.lines().count();
    eprintln!("parity: {passed}/{total} cases match the Python oracle");
    if !failures.is_empty() {
        for failure in failures.iter().take(20) {
            eprintln!("  MISMATCH {failure}");
        }
        panic!("{} parity case(s) failed", failures.len());
    }
}
